mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.z += time * 1.0;
  vec3 q = p;
  q.z = mod(q.z, 2.0) - 1.0;
  float rib = length(vec2(length(q.xy) - 1.5, q.z)) - 0.15;
  float wall = 1.6 - length(p.xy);
  return min(rib, wall);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -1.0);
  vec3 rd = normalize(vec3(p, 1.4));
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 14.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.02, 0.03, 0.02);
  if (t < 14.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(
      map(pos + e.xyy) - map(pos - e.xyy),
      map(pos + e.yxy) - map(pos - e.yxy),
      map(pos + e.yyx) - map(pos - e.yyx)
    ));
    vec3 l = normalize(vec3(0.0, 1.0, -1.0));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 64.0);
    float fog = 1.0 / (1.0 + t * t * 0.03);
    col = (vec3(0.05, 0.07, 0.05) + diff * vec3(0.2, 0.35, 0.2) + spec * vec3(0.8, 1.0, 0.8)) * fog;
  }
  ret = col;
}
